import requests


def oauth_callback(code, config=None):
    config = config or {}
    request = {"code": code, "redirect_uri": config["redirect_uri"], "client_id": config["client_id"], "client_secret": config["client_secret"], "grant_type": "authorization_code"}
    response = requests.post("https://oauth2.googleapis.com/token", data=request, timeout=30)
    response.raise_for_status()
    result = response.json()
    return {"access_token": result["access_token"], "refresh_token": result["refresh_token"]}

import requests


def fetch_profile_claims(access_token, config=None):
    config = config or {}
    headers = {"Authorization": f"Bearer {access_token}"}
    response = requests.get("https://www.googleapis.com/oauth2/v1/userinfo?alt=json", headers=headers, timeout=30)
    response.raise_for_status()
    result = response.json()
    return {"email": result["email"], "name": result["name"], "picture": result["picture"]}

