import json


def summarize_audit_events(audit_events):
    summary = {}
    for event in audit_events:
        if event["provider_id"] not in summary:
            summary[event["provider_id"]] = {"success": 0, "failure": 0}
        if event["status"] == "success":
            summary[event["provider_id"]]["success"] += 1
        else:
            summary[event["provider_id"]]["failure"] += 1
    return json.dumps(summary, indent=4)

import re


def moderate_claims(claims):
    moderated_claims = {}
    for key, value in claims.items():
        if isinstance(value, str):
            value = re.sub(r'[^a-zA-Z0-9\s]', '', value)
        moderated_claims[key] = value
    return moderated_claims

import boto3


def store_audit_record(record):
    client = boto3.client('dynamodb')
    client.put_item(
        TableName='FederatedLoginAudit',
        Item={
            'id': {'S': record['id']},
            'provider_id': {'S': record['provider_id']},
            'timestamp': {'S': record['timestamp']},
            'status': {'S': record['status']}
        }
    )
